let listRenders = 0
const rowRenders = {}

function Row({ item, toggle }) {
  rowRenders[item.id] = (rowRenders[item.id] ?? 0) + 1
  return (
    <label className="rowd">
      <input type="checkbox" checked={item.done} onChange={() => toggle(item.id)} />
      {item.text} <span className="rc">{rowRenders[item.id]}</span>
    </label>
  )
}

function List() {
  listRenders++
  const [items, setItems] = useState(seed)
  const toggle = (id) => setItems((xs) => ({ ...xs, [id]: { ...xs[id], done: !xs[id].done } }))
  return (
    <div>
      <div className="demo-head">list <span className="rc">{listRenders}</span></div>
      {Object.values(items).map((it) => <Row key={it.id} item={it} toggle={toggle} />)}
    </div>
  )
}
return <List />

