// These controls use the same named actions and history as the code example.
function Editor() {
  const n = store.usePath('/n')
  const label = store.usePath('/label')
  const [, tick] = useReducer((x) => x + 1, 0)
  return (
    <div className="undo-demo">
      <p>Change this task, then use Undo to recover the previous value.</p>
      <div className="undo-demo-fields">
        <label>Task title<input className="pg-input" value={label}
          onChange={(e) => setLabel(e.target.value)} /></label>
        <label>Estimate<input className="pg-input" type="number" value={n}
          onChange={(e) => setN(Number(e.target.value))} /></label>
      </div>
      <div className="rowd undo-demo-actions">
        <button className="tab" onClick={() => { store.undo(); tick() }} disabled={!store.canUndo}>Undo</button>
        <button className="tab" onClick={() => { store.redo(); tick() }} disabled={!store.canRedo}>Redo</button>
      </div>
      <p className="lnote" aria-live="polite">{store.log.length} recorded changes · {store.cursor + 1} currently applied.</p>
      <p className="lnote">A new edit after Undo replaces the redo branch. Reset example restores the starting session.</p>
    </div>
  )
}
return <Editor />
